function initializeCharts(){console.log("Charts initialized")}document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".card-stats");t.length>0&&t.forEach(t=>{t.addEventListener("mouseenter",function(){this.style.transform="translateY(-5px)",this.style.boxShadow="0 10px 20px rgba(0, 0, 0, 0.1)"}),t.addEventListener("mouseleave",function(){this.style.transform="translateY(0)",this.style.boxShadow=""})});const e=document.querySelectorAll(".quick-links-btn");e.length>0&&e.forEach(t=>{t.addEventListener("mousedown",function(){this.style.transform="translateY(2px)"}),t.addEventListener("mouseup",function(){this.style.transform="translateY(-2px)"}),t.addEventListener("mouseleave",function(){this.style.transform=""})}),initializeCharts()});